import requests
import uuid
import sys

BASE_URL = "http://localhost:8000"
TIMEOUT = 30


def test_register_validation():
    session = requests.Session()
    headers = {"Content-Type": "application/json"}

    # 1) Password shorter than 8 -> 422
    short_pwd_email = f"short-{uuid.uuid4().hex}@utb.edu.co"
    payload_short_pwd = {"nombre": "Short Pass", "email": short_pwd_email, "password": "Ab1"}
    try:
        r = session.post(f"{BASE_URL}/identity/register", json=payload_short_pwd, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Request failed for short password case: {e}")
    assert r.status_code == 422, f"Expected 422 for short password, got {r.status_code}: {r.text}"

    # 2) Invalid email -> 422
    invalid_email = "not-an-email"
    payload_invalid_email = {"nombre": "Invalid Email", "email": invalid_email, "password": "ValidPass123"}
    try:
        r = session.post(f"{BASE_URL}/identity/register", json=payload_invalid_email, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Request failed for invalid email case: {e}")
    assert r.status_code == 422, f"Expected 422 for invalid email, got {r.status_code}: {r.text}"

    # 3) Already registered email ana@utb.edu.co -> 409
    existing_email = "ana@utb.edu.co"
    payload_existing = {"nombre": "Ana Duplicate", "email": existing_email, "password": "Comprador-2026"}
    try:
        r = session.post(f"{BASE_URL}/identity/register", json=payload_existing, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Request failed for existing email case: {e}")
    assert r.status_code == 409, f"Expected 409 for already registered email, got {r.status_code}: {r.text}"

    # 4) Unique valid email -> 201 with roles including {codigo: 'comprador'}
    unique_email = f"user-{uuid.uuid4().hex}@utb.edu.co"
    unique_password = "ValidPass-2026"
    payload_unique = {"nombre": "Unique User", "email": unique_email, "password": unique_password}

    created = False
    try:
        try:
            r = session.post(f"{BASE_URL}/identity/register", json=payload_unique, headers=headers, timeout=TIMEOUT)
        except requests.RequestException as e:
            raise AssertionError(f"Request failed for unique valid email case: {e}")

        assert r.status_code == 201, f"Expected 201 for successful registration, got {r.status_code}: {r.text}"

        # Validate response contains roles with codigo 'comprador'
        try:
            body = r.json()
        except ValueError:
            raise AssertionError(f"Response is not JSON for successful registration: {r.text}")

        roles = body.get("roles") if isinstance(body, dict) else None
        assert isinstance(roles, list), f"Expected 'roles' list in response, got: {body}"

        has_comprador = any((isinstance(role, dict) and role.get("codigo") == "comprador") for role in roles)
        assert has_comprador, f"Expected a role with codigo 'comprador' in roles, got: {roles}"

        created = True

    finally:
        # Cleanup: attempt to delete the created account if it was created.
        if created:
            # Try to login as the created user to obtain token
            login_payload = {"email": unique_email, "password": unique_password}
            try:
                lr = session.post(f"{BASE_URL}/identity/login", json=login_payload, headers=headers, timeout=TIMEOUT)
            except requests.RequestException as e:
                print(f"Cleanup warning: login failed for cleanup: {e}", file=sys.stderr)
                return

            if lr.status_code != 200:
                print(f"Cleanup warning: login returned {lr.status_code}, cannot delete account. Response: {lr.text}", file=sys.stderr)
                return

            try:
                token_body = lr.json()
            except ValueError:
                print(f"Cleanup warning: login response not JSON: {lr.text}", file=sys.stderr)
                return

            access_token = token_body.get("access_token")
            if not access_token:
                print(f"Cleanup warning: no access_token in login response: {token_body}", file=sys.stderr)
                return

            auth_headers = {"Authorization": f"Bearer {access_token}"}
            # Attempt to DELETE /identity/me to remove the created account (common pattern)
            try:
                dr = session.delete(f"{BASE_URL}/identity/me", headers=auth_headers, timeout=TIMEOUT)
            except requests.RequestException as e:
                print(f"Cleanup warning: delete request failed: {e}", file=sys.stderr)
                return

            if dr.status_code not in (200, 204):
                # If deletion endpoint not available or returns different code, warn but don't fail the test
                print(f"Cleanup warning: delete returned {dr.status_code}: {dr.text}", file=sys.stderr)


if __name__ == "__main__":
    test_register_validation()
    print("TC031 register_validation completed successfully.")

import requests
import uuid
import sys

BASE_URL = "http://localhost:8000"
TIMEOUT = 30

def test_login_wrong_password_401():
    url = f"{BASE_URL}/identity/login"
    headers = {"Content-Type": "application/json", "Accept": "application/json"}

    # Case 1: known user with wrong password
    payload_known_wrong = {"email": "ana@utb.edu.co", "password": "Comprador-WRONG-123"}
    try:
        resp_known = requests.post(url, json=payload_known_wrong, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise SystemExit(f"HTTP request failed for known user wrong password: {e}")

    assert resp_known.status_code == 401, f"Expected 401 for wrong password, got {resp_known.status_code}. Body: {resp_known.text}"
    try:
        json_known = resp_known.json()
    except ValueError:
        raise AssertionError(f"Response for wrong password is not valid JSON: {resp_known.text}")

    detail_known = json_known.get("detail")
    assert detail_known is not None, f"'detail' missing in response for wrong password: {json_known}"

    # Case 2: unknown email (must produce the same 401 detail to avoid user enumeration)
    unknown_email = f"unknown-{uuid.uuid4()}@utb.edu.co"
    payload_unknown = {"email": unknown_email, "password": "SomePassword123!"}
    try:
        resp_unknown = requests.post(url, json=payload_unknown, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise SystemExit(f"HTTP request failed for unknown email: {e}")

    assert resp_unknown.status_code == 401, f"Expected 401 for unknown email, got {resp_unknown.status_code}. Body: {resp_unknown.text}"
    try:
        json_unknown = resp_unknown.json()
    except ValueError:
        raise AssertionError(f"Response for unknown email is not valid JSON: {resp_unknown.text}")

    detail_unknown = json_unknown.get("detail")
    assert detail_unknown is not None, f"'detail' missing in response for unknown email: {json_unknown}"

    # The details must be identical to prevent user enumeration
    assert detail_known == detail_unknown, (
        "Expected identical 'detail' message for wrong password and unknown email to prevent user enumeration. "
        f"Got: known={detail_known!r}, unknown={detail_unknown!r}"
    )

    print("TC032 passed: wrong password and unknown email both returned 401 with identical detail.")

if __name__ == "__main__":
    test_login_wrong_password_401()

import requests
import sys
from typing import Any, Dict, List

BASE = "http://localhost:8000"
TIMEOUT = 30.0

def login(email: str, password: str) -> str:
    url = f"{BASE}/identity/login"
    try:
        resp = requests.post(url, json={"email": email, "password": password}, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Login request failed for {email}: {e}") from e

    if resp.status_code != 200:
        raise AssertionError(f"Expected 200 from {url} for {email}, got {resp.status_code}: {resp.text}")

    try:
        body = resp.json()
    except ValueError:
        raise AssertionError(f"Login response for {email} is not valid JSON: {resp.text}")

    token = body.get("access_token")
    if not token:
        raise AssertionError(f"No access_token in login response for {email}: {body}")

    return token

def get_me(token: str) -> Dict[str, Any]:
    url = f"{BASE}/identity/me"
    headers = {"Authorization": f"Bearer {token}"}
    try:
        resp = requests.get(url, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"GET /identity/me request failed: {e}") from e

    if resp.status_code != 200:
        raise AssertionError(f"Expected 200 from {url}, got {resp.status_code}: {resp.text}")

    try:
        return resp.json()
    except ValueError:
        raise AssertionError(f"/identity/me response is not valid JSON: {resp.text}")

def assert_role_present(roles: List[Dict[str, Any]], codigo: str, tienda_id: int = None) -> None:
    if not isinstance(roles, list):
        raise AssertionError(f"roles is not a list: {roles}")

    for r in roles:
        if not isinstance(r, dict):
            continue
        if r.get("codigo") != codigo:
            continue
        if tienda_id is None:
            # only codigo required
            return
        # handle tienda_id possibly as int or str
        try:
            rid = r.get("tienda_id")
            if rid is None:
                continue
            if int(rid) == tienda_id:
                return
        except (ValueError, TypeError):
            continue

    if tienda_id is None:
        raise AssertionError(f"Role with codigo '{codigo}' not found in roles: {roles}")
    else:
        raise AssertionError(f"Role with codigo '{codigo}' and tienda_id {tienda_id} not found in roles: {roles}")

def test_me_returns_roles_per_store():
    # Store admin: admin.almuerzo-01@utb.edu.co / Tienda-2026 -> tienda_id 4, admin_tienda role
    store_admin_email = "admin.almuerzo-01@utb.edu.co"
    store_admin_password = "Tienda-2026"

    token_store_admin = login(store_admin_email, store_admin_password)
    me_store_admin = get_me(token_store_admin)

    roles_sa = me_store_admin.get("roles")
    assert roles_sa is not None, f"/identity/me did not include 'roles' for {store_admin_email}: {me_store_admin}"
    assert_role_present(roles_sa, "admin_tienda", tienda_id=4)

    print(f"Store admin {store_admin_email} has admin_tienda role for tienda_id 4.")

    # General admin: admin@utb.edu.co / Admin-Demo-2026 -> roles include admin_general
    general_admin_email = "admin@utb.edu.co"
    general_admin_password = "Admin-Demo-2026"

    token_general_admin = login(general_admin_email, general_admin_password)
    me_general_admin = get_me(token_general_admin)

    roles_ga = me_general_admin.get("roles")
    assert roles_ga is not None, f"/identity/me did not include 'roles' for {general_admin_email}: {me_general_admin}"
    assert_role_present(roles_ga, "admin_general")

    print(f"General admin {general_admin_email} has admin_general role.")

if __name__ == "__main__":
    try:
        test_me_returns_roles_per_store()
        print("TC033 passed.")
    except AssertionError as e:
        print(f"TC033 failed: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"TC033 unexpected error: {e}", file=sys.stderr)
        sys.exit(2)

import requests
import sys
import json
from typing import Any

BASE_URL = "http://localhost:8000"
TIMEOUT = 30


def _find_value_recursively(obj: Any, target: str) -> bool:
    if isinstance(obj, str):
        return obj == target
    if isinstance(obj, dict):
        for k, v in obj.items():
            if _find_value_recursively(v, target):
                return True
    if isinstance(obj, list):
        for item in obj:
            if _find_value_recursively(item, target):
                return True
    return False


def test_product_detail_and_stores():
    # Login to obtain token
    login_url = f"{BASE_URL}/identity/login"
    login_payload = {"email": "ana@utb.edu.co", "password": "Comprador-2026"}
    try:
        resp = requests.post(login_url, json=login_payload, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"Login request failed: {e}")
    assert resp.status_code == 200, f"Login failed (status {resp.status_code}): {resp.text}"
    try:
        token_data = resp.json()
    except ValueError:
        raise AssertionError(f"Login response is not valid JSON: {resp.text}")
    access_token = token_data.get("access_token")
    assert access_token, f"No access_token returned in login response: {token_data}"

    headers = {"Authorization": f"Bearer {access_token}"}

    # GET /catalog/products/25 -> 200 and contains tienda 'punto-fit'
    prod25_url = f"{BASE_URL}/catalog/products/25"
    try:
        resp = requests.get(prod25_url, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"GET {prod25_url} failed: {e}")
    assert resp.status_code == 200, f"Expected 200 for product 25, got {resp.status_code}: {resp.text}"
    try:
        prod25_json = resp.json()
    except ValueError:
        raise AssertionError(f"Product 25 response is not valid JSON: {resp.text}")

    contains_punto_fit = _find_value_recursively(prod25_json, "punto-fit")
    assert contains_punto_fit, f"Product 25 JSON does not contain tienda 'punto-fit'. Response: {json.dumps(prod25_json, ensure_ascii=False)}"

    # GET /catalog/products/999999 -> 404
    prod_missing_url = f"{BASE_URL}/catalog/products/999999"
    try:
        resp = requests.get(prod_missing_url, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"GET {prod_missing_url} failed: {e}")
    assert resp.status_code == 404, f"Expected 404 for missing product, got {resp.status_code}: {resp.text}"

    # GET /catalog/tiendas -> 5 stores
    tiendas_url = f"{BASE_URL}/catalog/tiendas"
    try:
        resp = requests.get(tiendas_url, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        raise AssertionError(f"GET {tiendas_url} failed: {e}")
    assert resp.status_code == 200, f"Expected 200 for /catalog/tiendas, got {resp.status_code}: {resp.text}"
    try:
        tiendas_json = resp.json()
    except ValueError:
        raise AssertionError(f"/catalog/tiendas response is not valid JSON: {resp.text}")
    assert isinstance(tiendas_json, list), f"/catalog/tiendas did not return a list: {type(tiendas_json).__name__}"
    assert len(tiendas_json) == 5, f"Expected 5 stores from /catalog/tiendas, got {len(tiendas_json)}. Response: {json.dumps(tiendas_json, ensure_ascii=False)}"

    print("TC035 product_detail_and_stores: PASS")


if __name__ == "__main__":
